package vn.com.apartment.billing;
import jakarta.validation.Valid;import jakarta.validation.constraints.*;import java.math.BigDecimal;import java.net.URLEncoder;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.time.LocalDateTime;import java.util.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.*;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;
@RestController @RequestMapping("/api/qr-payments") public class QrPaymentController{
 private final PaymentQrRequestRepository qrRequests;private final ReceivableItemRepository items;private final BankPaymentReconciliationService reconciliation;private final ReceivableRepository receivables;private final PaymentNotificationService notificationService;private final String bankCode,bankAccount,accountName,webhookSecret;
 public QrPaymentController(PaymentQrRequestRepository qrRequests,ReceivableItemRepository items,BankPaymentReconciliationService reconciliation,ReceivableRepository receivables,PaymentNotificationService notificationService,@Value("${app.payment.bank-code}") String bankCode,@Value("${app.payment.bank-account}") String bankAccount,@Value("${app.payment.account-name}") String accountName,@Value("${app.payment.webhook-secret}") String webhookSecret){this.qrRequests=qrRequests;this.items=items;this.reconciliation=reconciliation;this.receivables=receivables;this.notificationService=notificationService;this.bankCode=bankCode;this.bankAccount=bankAccount;this.accountName=accountName;this.webhookSecret=webhookSecret;}
 @PostMapping("/items/{itemId}") @Transactional public QrResponse create(@PathVariable Long itemId){ReceivableItem item=items.findById(itemId).orElseThrow(()->notFound("Không tìm thấy dịch vụ phải thu."));if(item.outstanding().signum()<=0)throw conflict("Dịch vụ đã được thanh toán đủ.");for(PaymentQrRequest old:qrRequests.findPendingByItem(itemId))old.expire();PaymentQrRequest qr=new PaymentQrRequest(item.getReceivable(),reference("QR"+itemId),bankCode,bankAccount,LocalDateTime.now().plusDays(7));qr.addAllocation(item,item.outstanding());return response(qrRequests.save(qr));}
 @PostMapping("/grouped") @Transactional public QrResponse createGrouped(@Valid @RequestBody GroupedQrRequest request){List<ReceivableItem> selected=items.findAllById(request.itemIds());if(selected.size()!=new HashSet<>(request.itemIds()).size())throw bad("Có dịch vụ không tồn tại hoặc bị chọn trùng.");Receivable bill=selected.getFirst().getReceivable();if(selected.stream().anyMatch(i->!i.getReceivable().getId().equals(bill.getId())))throw bad("Chỉ được gộp các dịch vụ trong cùng một khoản phải thu.");PaymentQrRequest qr=new PaymentQrRequest(bill,reference("QRG"+bill.getId()),bankCode,bankAccount,LocalDateTime.now().plusDays(7));for(ReceivableItem item:selected){if(item.outstanding().signum()<=0)throw conflict("Dịch vụ "+item.getDescription()+" đã thanh toán đủ.");for(PaymentQrRequest old:qrRequests.findPendingByItem(item.getId()))old.expire();qr.addAllocation(item,item.outstanding());}return response(qrRequests.save(qr));}
 @GetMapping @Transactional(readOnly=true) public List<QrListResponse> list(){return qrRequests.findAllDetailed().stream().map(q->{Receivable r=q.getReceivable();String location=r.isCommercial()?r.getCommercialSpace().getCode():r.getUnit().getCode();return new QrListResponse(q.getId(),q.getReferenceCode(),location,q.getAllocations().stream().map(a->a.getReceivableItem().getDescription()).reduce((a,b)->a+", "+b).orElse("Dịch vụ"),q.getAmount(),q.getStatus(),q.getCreatedAt(),q.getPaidAt());}).toList();}
 @PostMapping("/send/receivables/{receivableId}") @Transactional public SendResponse sendOne(@PathVariable Long receivableId,@RequestBody(required=false) SendRequest request){Receivable bill=receivables.findById(receivableId).orElseThrow(()->notFound("Không tìm thấy khoản phải thu."));return sendBill(bill,request==null?"AUTO":request.channel());}
 @PostMapping("/send-bulk") @Transactional public SendResponse sendBulk(@RequestParam(required=false) Long periodId,@RequestBody(required=false) SendRequest request){int sent=0,failed=0,skipped=0;for(Receivable bill:receivables.search(periodId)){if(bill.outstanding().signum()<=0){skipped++;continue;}SendResponse result=sendBill(bill,request==null?"AUTO":request.channel());sent+=result.sent();failed+=result.failed();skipped+=result.skipped();}return new SendResponse(sent,failed,skipped);}
 @PostMapping("/webhook/bank") public WebhookResponse webhook(@RequestHeader(value="X-Webhook-Secret",required=false) String secret,@Valid @RequestBody BankWebhookRequest request){if(!secretMatches(secret))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Webhook secret không hợp lệ.");BankPaymentReconciliationService.Result result=reconciliation.reconcile(request.provider(),request.transactionId(),request.creditAccount(),request.amount(),request.description(),request.transactionTime()==null?LocalDateTime.now():request.transactionTime(),null,json(request));return new WebhookResponse(result.status(),result.referenceCode(),result.message());}
 private QrResponse response(PaymentQrRequest q){String base="https://img.vietqr.io/image/"+enc(q.getBankCode())+"-"+enc(q.getBankAccount())+"-compact2.png";String url=base+"?amount="+q.getAmount().toBigInteger()+"&addInfo="+enc(q.getReferenceCode())+"&accountName="+enc(accountName);return new QrResponse(q.getId(),q.getReferenceCode(),q.getAmount(),bankCode,bankAccount,accountName,url,q.getStatus(),q.getExpiresAt());}private String reference(String prefix){return prefix+"-"+UUID.randomUUID().toString().replace("-","").substring(0,10).toUpperCase();}private boolean secretMatches(String supplied){return supplied!=null&&MessageDigest.isEqual(webhookSecret.getBytes(StandardCharsets.UTF_8),supplied.getBytes(StandardCharsets.UTF_8));}private String enc(String v){return URLEncoder.encode(v,StandardCharsets.UTF_8);}private String json(Object v){return String.valueOf(v);}private ResponseStatusException notFound(String m){return new ResponseStatusException(HttpStatus.NOT_FOUND,m);}private ResponseStatusException conflict(String m){return new ResponseStatusException(HttpStatus.CONFLICT,m);}private ResponseStatusException bad(String m){return new ResponseStatusException(HttpStatus.BAD_REQUEST,m);}
 private SendResponse sendBill(Receivable bill,String channel){if(bill.isCommercial())return new SendResponse(0,0,(int)bill.getItems().stream().filter(i->i.outstanding().signum()>0).count());int sent=0,failed=0,skipped=0;for(ReceivableItem item:bill.getItems()){if(item.outstanding().signum()<=0){skipped++;continue;}try{QrResponse created=create(item.getId());PaymentQrRequest qr=qrRequests.findDetailedByReference(created.referenceCode()).orElseThrow();PaymentNotification notification=notificationService.send(qr,bill.getCustomer(),channel,created.qrImageUrl());if("SENT".equals(notification.getStatus()))sent++;else failed++;}catch(Exception e){failed++;}}return new SendResponse(sent,failed,skipped);}
 public record QrResponse(Long id,String referenceCode,BigDecimal amount,String bankCode,String bankAccount,String accountName,String qrImageUrl,String status,LocalDateTime expiresAt){}public record QrListResponse(Long id,String referenceCode,String unitCode,String serviceName,BigDecimal amount,String status,LocalDateTime createdAt,LocalDateTime paidAt){}public record GroupedQrRequest(@NotEmpty List<@NotNull Long> itemIds){}public record BankWebhookRequest(@NotBlank String provider,@NotBlank String transactionId,String creditAccount,@NotNull @DecimalMin("0.01") BigDecimal amount,String description,LocalDateTime transactionTime){}public record WebhookResponse(String status,String referenceCode,String message){}public record SendRequest(String channel){}public record SendResponse(int sent,int failed,int skipped){}
}
